      <thead>
        <tr>
          <th>Product</th>
          <th>Price</th>
          <th>Action</th>
        </tr>
      </thead>
      <tbody>
        {/* ... */}
      </tbody>
      <tfoot>
        {/* ... */}
      </tfoot>
    </table>
  </div>
</div>
      </div>
    </div>
  );
}

export default ProductDetails;
